prts.feedbackvariables:
studplane: ans1*x+ans2*y+ans3*z+ans4=0;
isplane: not is(ans1=0 and ans2=0 and ans3=0);
pointonstudplane: check_point(studplane, p4);

studnormal: if(isplane) then myuvect([ans1,ans2,ans3]) else [0,0,1];
studangle: qunormal.studnormal;
iscorangle: is(abs(float(abs(studangle)-abs(cos(angle))))<10^-9)
